@FRASTM 
I work together with tt0776 on the same Zephyr based project.

We have now got much further implementing the interface between a stm32l476 based system and a Microchip SST26VF QSpi flash chip running under Zephyr.

As tt077 mentioned earlier, the standard STM32CubeMx stm32l476xx and stm32l486xx libraries does not support the Global Block Protection Unlock instruction (ULBPR - 98H), which is required for being able to program the Microchip flash. 
"qspi is failing in compile stm32l476xx + stm32l486xx ..." (https://github.com/zephyrproject-rtos/zephyr/discussions/68423)

Therefor we have made a git patch, that adds the definitions of QUADSPI_CR_DFM and QUADSPI_CR_FSEL to stm32l476xx.h and stm32l486xx.h, see (https://github.com/zephyrproject-rtos/zephyr/discussions/68423)

Another challenge we have also discovered, is that Microchip SST26VF QSpi flash chips supports the SPI Quad Page Program instruction (32H), but unlike other chip manufacturers, the instruction expect this instruction as 1-4-4, and not 1-1-4 as normal.

Also here we have implemented a git patch, that updates flash_stm32_qspi.c to fix this issue, controlled by a Kconfig symbol: `USE_MICROCHIP_QSPI_FLASH_WITH_STM32`.

I have attached the patch that fixes the problem for us, in the hope that it can be a help for others facing similar problems.

Kconfig.board:
```
config USE_MICROCHIP_QSPI_FLASH_WITH_STM32 
   bool "Include patch for Microchip qspi flash when running with stm32"
   default y
   depends on BOARD_XXXX

```
Patch:
```
diff --git a/drivers/flash/flash_stm32_qspi.c b/drivers/flash/flash_stm32_qspi.c
index 4090cd41bb..b955fc58d9 100644
--- a/drivers/flash/flash_stm32_qspi.c
+++ b/drivers/flash/flash_stm32_qspi.c
@@ -174,9 +174,18 @@ static inline int qspi_prepare_quad_program(const struct device *dev,
 			dev_data->qspi_write_cmd == SPI_NOR_CMD_PP_1_4_4);
 
 	cmd->Instruction = dev_data->qspi_write_cmd;
+
+#if defined(CONFIG_USE_MICROCHIP_QSPI_FLASH_WITH_STM32)
+	if (cmd->Instruction == SPI_NOR_CMD_PP_1_1_4)
+	{
+		cmd->AddressMode = QSPI_ADDRESS_4_LINES;
+	}
+#else
 	cmd->AddressMode = ((cmd->Instruction == SPI_NOR_CMD_PP_1_1_4)
 				? QSPI_ADDRESS_1_LINE
 				: QSPI_ADDRESS_4_LINES);
+#endif
+
 	cmd->DataMode = QSPI_DATA_4_LINES;
 	cmd->DummyCycles = 0;
 
@@ -247,6 +256,41 @@ static int qspi_read_access(const struct device *dev, QSPI_CommandTypeDef *cmd,
 	return dev_data->cmd_status;
 }
 
+#if defined(CONFIG_USE_MICROCHIP_QSPI_FLASH_WITH_STM32)
+static int flash_unprotect(const struct device *dev)
+{
+	int ret = 0;
+
+	QSPI_CommandTypeDef cmd_write_en = {
+		.Instruction = SPI_NOR_CMD_WREN,
+		.InstructionMode = QSPI_INSTRUCTION_1_LINE,
+	};
+
+	QSPI_CommandTypeDef cmd_unprotect = {
+		.Instruction = SPI_NOR_CMD_ULBPR,
+		.InstructionMode = QSPI_INSTRUCTION_1_LINE,
+	};
+
+	ret = qspi_send_cmd(dev, &cmd_write_en);
+
+	if (ret != 0) {
+		printf("\n%s SPI flash unprotect WREN failed: %d\n", dev->name, ret);
+	}
+
+	ret = qspi_send_cmd(dev, &cmd_unprotect);
+
+	if (ret == 0) {
+		printf("\n%s SPI flash unprotect success.\n", dev->name);
+	}
+	else
+	{
+		printf("\n%s SPI flash unprotect failed - status: %d\n", dev->name, ret);
+	}
+	
+	return ( ret );
+}
+#endif
+
 /*
  * Perform a write access over QSPI bus.
  */
@@ -1337,6 +1381,10 @@ static int flash_stm32_qspi_init(const struct device *dev)
 	}
 #endif /* CONFIG_FLASH_PAGE_LAYOUT */
 
+#if defined(CONFIG_USE_MICROCHIP_QSPI_FLASH_WITH_STM32)
+	flash_unprotect(dev);
+#endif
+
 	return 0;
 }
 

```

